import unittest

from hourglass.rounding import label_spans, round_spans
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpansTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        result = round_spans([Span(544, 1028)], 15)
        self.assertEqual(result, [Span(540, 1035)])

    def test_halfway_goes_up(self):
        result = round_spans([Span(65, 125)], 10)
        self.assertEqual(result, [Span(70, 130)])

    def test_aligned_spans_are_unchanged(self):
        spans = [Span(60, 120), Span(600, 900)]
        self.assertEqual(round_spans(spans, 30), spans)

    def test_end_of_day_stays_valid(self):
        result = round_spans([Span(1400, 1439)], 30)
        self.assertEqual(result, [Span(1410, 1440)])

    def test_empty_list(self):
        self.assertEqual(round_spans([], 15), [])

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(541, 542)], 15)

class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 61, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_good_steps_work(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                round_spans([Span(60, 240)], step)

class LabelTests(unittest.TestCase):
    def test_label_after_rounding(self):
        spans = [parse_span("09:02-17:14")]
        self.assertEqual(
            label_spans(spans, 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_whole_hours(self):
        spans = [parse_span("08:00-12:00")]
        self.assertEqual(
            label_spans(spans, 60),
            ["08:00-12:00 (4h 0m)"],
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 270)]
        self.assertEqual(len(label_spans(spans, 30)), 2)

    def test_bad_step_raises(self):
        with self.assertRaises(ValueError):
            label_spans([Span(60, 120)], 0)

if __name__ == "__main__":
    unittest.main()
